#!/usr/bin/env python3
"""drug/de_novo_generative — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "de_novo_generative"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'de_novo_generative', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """REINVENT 4.7.15 de novo molecular generation — host_env=praxis-drug-reinvent。
    输入:mode (sampling/staged_learning) / prior_model / n_samples / config_toml (可选)
    输出:n_generated / smiles_list / scaffold_diversity / out_csv
    """
    import os as _os
    import tempfile as _tempfile
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    n_samples = int(payload.get("n_samples", 100))
    config_toml = payload.get("config_toml")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_samples": n_samples, "tool": "reinvent4"}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_generated": 0, "smiles_list": [],
                "out_csv": "", "diagnostics": {**diagnostics, "dry": True}}
    if not config_toml or not _os.path.isfile(config_toml):
        return {"ok": False,
                "error": "需要 config_toml 路径(REINVENT 4 TOML 配置文件,定义 prior_model / scoring)",
                "hint": "示例见 reinvent4 自带 configs/; 缺这个无法跑",
                "diagnostics": diagnostics}

    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="reinvent_")
    out_csv = _os.path.join(out_dir, "sampled.csv")
    diagnostics["out_dir"] = out_dir
    cmd = ["reinvent", "-l", _os.path.join(out_dir, "reinvent.log"), config_toml]
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 1800)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "reinvent 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    # reinvent 输出在 config 指定路径,这里仅 stub 返回基本元信息
    return {"ok": True, "skill_id": SKILL, "n_generated": n_samples,
            "smiles_list": [], "out_csv": out_csv,
            "diagnostics": {**diagnostics, "note": "smiles 收集需按 config 的 output 字段读取"}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
